#!/usr/bin/env python3
# Some portions generated by Codex. Genuine Workbench delivery; no browser claim from Node timings.
import argparse,pathlib,subprocess,fcntl,os,time,json,urllib.request,shutil,hashlib
p=argparse.ArgumentParser();p.add_argument('arm',choices=['base','stack','ordered','both']);p.add_argument('name');p.add_argument('--warmups',type=int,default=60);p.add_argument('--iterations',type=int,default=30);p.add_argument('--validate',action='store_true');p.add_argument('--browser',action='store_true');a=p.parse_args()
r=pathlib.Path(__file__).resolve().parents[3];os.chdir(r);d=pathlib.Path(__file__).resolve().parent; common=d.parent/'depth-workbench'
out=d/'runs'/a.name;assert not out.exists(),'Refuse replacing prior run';out.mkdir(parents=True)
lock=open(r/'experiments/overlay/native-benchmark.lock','w');fcntl.flock(lock,fcntl.LOCK_EX)
cp=str(d/'profile-harness')+':'+(d/f'cp-{a.arm}.txt').read_text().strip();java=r.parent/'toolchain/jdk-25.0.5+8/bin/java'
flags={'rdf4j.lmdb.nativeQueryEngine.enabled':'true','rdf4j.lmdb.janinoCodegen.enabled':'true','rdf4j.lmdb.janinoCodegen.synchronous':'true','rdf4j.lmdb.janinoCodegen.thresholdRows':'0','rdf4j.lmdb.kernelInterpreter.enabled':'false','rdf4j.lmdb.parallel.enabled':'false','rdf4j.lmdb.irKernelParallel.enabled':'false','rdf4j.lmdb.valueOverlay.maxBytes':'268435456','rdf4j.lmdb.nativeDistinct.kernelGrouping':'true','rdf4j.lmdb.nativeValueMemo.enabled':'true','rdf4j.lmdb.repository.partialReady':'true','rdf4j.lmdb.nativeDistinct.widePrimitive':'true','rdf4j.lmdb.expressionDomain.bulkIdRecordIo':'true','rdf4j.lmdb.expressionDomain.reuseMembershipMissSlot':'true','rdf4j.lmdb.queryMemory.maxBytes':'2684354560','rdf4j.lmdb.queryMemory.perQueryMaxBytes':'671088640','rdf4j.sail.compactResultSnapshots':'true','rdf4j.http.compactIdentityMapping':'true','rdf4j.sail.compactSequentialLookup':'false','org.eclipse.rdf4j.appdata.basedir':str(common/'appdata')}
cmd=[str(java),'--enable-native-access=ALL-UNNAMED','-Xms2g','-Xmx5g','-XX:FlightRecorderOptions=stackdepth=128',f'-Dbench.profile.path={out}/profile.jfr',f'-Xlog:gc:file={out}/gc.log:time,uptime,level,tags',*[f'-D{k}={v}' for k,v in flags.items()],'-cp',cp,'bench.ProfileBenchmarkServer','--server.port=18080','--server.address=127.0.0.1','--logging.level.root=WARN']
manifest={'arm':a.arm,'source':json.loads((d/'source-identities.json').read_text())[a.arm],'command':cmd,'warmups':a.warmups,'iterations':a.iterations,'validate':a.validate,'scope':'Actual Server/Workbench to Node NDJSON, excludes browser rendering unless explicit browser mode','start':time.time()};(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
base='http://127.0.0.1:18080';log=open(out/'server.log','w');server=subprocess.Popen(cmd,stdout=log,stderr=subprocess.STDOUT)
try:
 for i in range(180):
  if server.poll() is not None:raise RuntimeError('Server exited; see server.log')
  try:urllib.request.urlopen(base+'/rdf4j-server/protocol',timeout=2).read();break
  except Exception:time.sleep(1)
 else:raise RuntimeError('Startup timeout')
 assert int(urllib.request.urlopen(base+'/rdf4j-server/repositories/bench/size',timeout=180).read())==26700
 assert urllib.request.urlopen(base+'/bench-ready',timeout=180).read()==b'ready'
 if a.browser:
  with open(out/'browser.log','w') as cl:subprocess.run(['node',str(d/'browser.mjs'),base,'100000',str(out/'browser.json')],stdout=cl,stderr=subprocess.STDOUT,check=True,timeout=300)
 else:
  for i in range(-a.warmups,a.iterations):
   if i==0: assert urllib.request.urlopen(base+'/bench-profile-start',timeout=60).read()==b'ok'
   stem=f'query-{i}';dest=out/(stem+'.json');mode='validate' if a.validate else 'measure'
   with open(out/(stem+'.log'),'w') as cl:subprocess.run(['node',str(common/'client.mjs'),base,'100000',str(dest),mode],stdout=cl,stderr=subprocess.STDOUT,check=True,timeout=180)
   x=json.loads(dest.read_text());b=x['before'];z=x['after']
   assert z['LmdbNativeKernelExecution:COMPILED_BINDS']>b['LmdbNativeKernelExecution:COMPILED_BINDS']
   assert z['LmdbNativeKernelExecution:INTERPRETED_BINDS']==b['LmdbNativeKernelExecution:INTERPRETED_BINDS']
   assert z['NativeExpressionDomain:SPILL_FILES_CREATED']==b['NativeExpressionDomain:SPILL_FILES_CREATED']
   assert z['NativeValueMemo:HITS']>b['NativeValueMemo:HITS']
   assert z['ledger:usedBytes']==b['ledger:usedBytes']
   assert 'binary' in z['tupleContentType'] and z['transportIdentityMapping'] and z['compactResultSnapshots'] and not z['compactSequentialLookup']
   expected='/read-depth/layer/' if a.arm in ('stack','both') else '/record-cancellation/baseline-classes/'
   assert z['org.eclipse.rdf4j.sail.lmdb.LmdbStoreConnection'].endswith(expected)
   storeExpected='/record-cancellation/baseline-classes/'
   assert z['org.eclipse.rdf4j.sail.lmdb.LmdbSailStore'].endswith(storeExpected)
   jar='/depth-workbench/runtime/BOOT-INF/lib/rdf4j-http-workbench-6.2.0-SNAPSHOT-classes.jar'
   writerExpected='/ordered-workbench/'+('base-candidate-layer/' if a.arm=='ordered' else 'stack-candidate-layer/') if a.arm in ('ordered','both') else ('/serializer-workbench/serializer-layer/' if a.arm=='stack' else jar)
   adapterExpected=writerExpected if a.arm in ('ordered','both') else jar
   assert z['org.eclipse.rdf4j.workbench.util.QueryEvaluator'].endswith(adapterExpected)
   assert z['org.eclipse.rdf4j.workbench.util.TupleResultBuilder'].endswith(adapterExpected)
   assert z['org.eclipse.rdf4j.workbench.util.WorkbenchPageResultWriter'].endswith(writerExpected)
   assert z['org.eclipse.rdf4j.sail.lmdb.evaluation.NativeValueMemo'].endswith('/record-cancellation/baseline-classes/')
   assert z['org.eclipse.rdf4j.query.resultio.binary.BinaryQueryResultWriter'].endswith('/depth-workbench/writer-on/')
   assert 'resource-restoration/layer' not in z['org.eclipse.rdf4j.http.client.QueryExecutionContext']
 assert urllib.request.urlopen(base+'/bench-profile-stop',timeout=60).read()==b'ok'
 manifest['profileScope']='Separate diagnostic; Node CPU absent; never pool with clean timing'
 manifest['finished']=time.time();manifest['status']='passed';(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
finally:
 server.terminate()
 try:server.wait(timeout=30)
 except subprocess.TimeoutExpired:server.kill();server.wait()
 log.close()
